[Theorem \ref{them: Detecting the FF center}/\ref{THM: FF center for gln1 vis pD op}/\ref{thm: character formula of the center}]\label{thm: A} \hspace{0mm}\\
\begin{enumerate}[leftmargin=*, labelsep=1em]
    \item There is an embedding of vertex algebras 
$$\mathfrak{z}(V^{\kk_c}(\gl_{n|1}))\hookrightarrow \pi_\mathfrak{h}^0,$$
whose image is generated by the coefficients of the pseudo-differential operator
$$(\partial_z- u_1(z))\cdots (\partial_z- u_n(z)) (\partial_z+u_{n+1}(z))^{-1}.$$
 \item There is a filtration on $\mathfrak{z}(V^{\kk_c}(\gl_{n|1}))$ whose associated graded differential algebra is isomorphic to the algebra of affine supersymmetric polynomials:
 \begin{align*}
 \operatorname{gr}\mathfrak{z}(V^{\kk_c}(\gl_{n|1}))\simeq \Lambda^{n|1}_{\mathrm{aff}}.
\end{align*}
 \item The $q$-character of the center $\mathfrak{z}(V^{\kk_c}(\gl_{n|1}))$ is given by
    \begin{align*}
    \operatorname{ch}[\mathfrak{z}(V^{\kk_c}(\gl_{n|1}))](q)=\frac{\sum_{m=0}^\infty (-1)^mq^{\frac{1}{2}m(m+1)}(q^{m+1};q)_{n-1}}{(q;q)_\infty^2(q,\cdots,q^{n-1};q)_\infty}.
\end{align*}
\end{enumerate}

ref_dict.thm: Wakimoto for sCoset:
\begin{theorem}\label{thm: Wakimoto for sCoset}\hspace{0mm}\\
\textup{(1) (\cite{CGN21})}
For $k \neq -\dC+1$, the embedding $\rho$ induces the embedding
\begin{align*}
    \Psi\colon C^\kk(\gl_{n|1}) \hookrightarrow  \pi^{k+\dC}_{\tori}
\end{align*}
which depends continuously on $\kk$ so that the generic image is characterized as the joint kernel of the screening operators
\begin{align*}
    C^\kk(\gl_{n|1}) \overset{\Psi}{\simeq} \bigcap_{i=1}^n \Ker S_i \subset \pi^{k+\dC}_{\tori}.
\end{align*} 
\textup{(2)} For the critical level $\kk=\kk_c$, i.e., $k=-\dC$, 
\begin{align*}
    C^{\kk_c}(\gl_{n|1})= \cent(\W^{\kk_c}(\gl_{n|1})).
\end{align*}
\end{theorem}

ref_dict.prop: Poisson str on the center:
\begin{proposition}\label{prop: Poisson str on the center}
The differential subalgebra $\mathrm{Fun}(\mathrm{Op}_{n|1}(D))$ is a Poisson vertex subalgebra of $\pi^0_\h$. This inherites a Poisson vertex algebra structure on $\cent(V^{\kk_c}(\gl_{n|1}))$ by the affine Harish-Chandra map.
\end{proposition}

