\begin{ThmLetter}[Theorem \ref{them: Detecting the FF center}/\ref{THM: FF center for gln1 vis pD op}/\ref{thm: character formula of the center}]\label{thm: A} \hspace{0mm}\\
\begin{enumerate}[leftmargin=*, labelsep=1em]
    \item There is an embedding of vertex algebras 
$$\cent(V^{\kk_c}(\gl_{n|1}))\hookrightarrow \pi_\h^0,$$
whose image is generated by the coefficients of the pseudo-differential operator
$$(\partial_z- u_1(z))\cdots (\partial_z- u_n(z)) (\partial_z+u_{n+1}(z))^{-1}.$$
 \item There is a filtration on $\cent(V^{\kk_c}(\gl_{n|1}))$ whose associated graded differential algebra is isomorphic to the algebra of affine supersymmetric polynomials:
 \begin{align*}
 \gr\cent(V^{\kk_c}(\gl_{n|1}))\simeq \Lambda^{n|1}_{\aff}.
\end{align*}
 \item The $q$-character of the center $\cent(V^{\kk_c}(\gl_{n|1}))$ is given by
    \begin{align*}
    \ch[\cent(V^{\kk_c}(\gl_{n|1}))](q)=\frac{\sum_{m=0}^\infty (-1)^mq^{\frac{1}{2}m(m+1)}(q^{m+1};q)_{n-1}}{(q;q)_\infty^2(q,\cdots,q^{n-1};q)_\infty}.
\end{align*}
\end{enumerate}
\end{ThmLetter}

ref_dict.Wsalg and Heisenberg coset:
\begin{align}\label{BRST complex}
C^\bullet_f(V^\kk(\g)):=V^\kk(\g)\otimes \bigwedge{}^{\bullet}(\g_+)
\end{align}
equipped with the differential $d=\int Y(Q,z) \mathrm{d}z$ where
\begin{align*}
    Q=\sum_{\alpha \in S_+} (-1)^{p({e}_\alpha)}(e_\alpha+(f|e_\alpha)) \psi_\alpha^*-\frac{1}{2} \sum_{\alpha,\beta,\gamma \in S_+} (-1)^{p({e}_\alpha)p({e}_\gamma)} c_{\alpha\beta}^\gamma \psi_\gamma \psi_\alpha^* \varphi_\beta^*
\end{align*}
where $(\cdot|\cdot)$ denote the normalized invariant bilinear form on $\g$.

By \cite{KW04}, one has the cohomology vanishing $\HH^{\neq0}(C_{f}^\bullet(V^\kk(\g)))=0$ and the vertex superalgebra obtained at the zero-th cohomology is called the $\W$-superalgebra associated with $(\g,f,\Gamma)$ at level $\kappa$. Since it only depends on the orbit $\OO$ containing $f$ and usually $\Gamma$ is clear, we will denote it as 
\begin{align*}
    \W^\kk(\g,\OO)=\HH^0(C_{f}^\bullet(V^\kk(\g))).
\end{align*}
Note that by replacing $V^\kk(\g)$ in \eqref{BRST complex} with $V^\kk(\g)$-modules $M$, we obtain $\W^\kk(\g,\OO)$-modules, giving rise to a functor
$$\HH_\OO(-)\colon V^\kk(\g)\Mod \rightarrow \W^\kk(\g,\OO)\Mod,\quad M \mapsto \HH^{0}(C_{f}^\bullet(M)).$$

\section{\tmath{$\W$}-superalgebra \tmath{$\W^{\kk}(\gl_{n|1})$} and Heisenberg coset}\label{Wsalg and Heisenberg coset}
\subsection{Regular \tmath{$\W$}-superalgebra} \label{sec: reg Wsalg}
Let $\g=\gl_{n|1}$ and $\g=\nil^+ \oplus \h \oplus \nil^-$ be the standard triangular decomposition. 
Then $\h$ is spanned by the $e_{1,1},\cdots, e_{n+1,n+1}$, $\nil^+$ is generated by $e_{1,2},\cdots,e_{n,n+1}$ which are root vectors corresponding to simple roots $\alpha_1,\cdots, \alpha_{n}$. 
We will identify $\h$ with its dual $\h^*$ by the bilinear form $\kk_V$ and thus 
$$\alpha_1=e_{1,1}-e_{2,2},\cdots, \alpha_{n-1}=e_{n-1,n-1}-e_{n,n},\quad \alpha_{n}=e_{n,n}+e_{n+1,n+1},$$
which are naturally identified with the coroots $h_i$, i.e., $h_i=\alpha_i$ for $i=1,\cdots,n$.

Let $n>1$ and take the regular nilpotent element
$$f=e_{2,1}+e_{3,2}+\cdots +e_{n,n-1}$$
in $\gl_{n|1}$ (resp. $\sll_{n|1}$)
and the good grading $\Gamma$ given by the weighted Dynkin diagram
\begin{center} 
\begin{tikzpicture}
{\dynkin[root
radius=.1cm,labels={\alpha_1,\alpha_2,\alpha_{n-1},\alpha_n},labels*={1,1,1,0},edge length=1cm]A{oo.ot}};
\end{tikzpicture}
\end{center}
and denote by $\W^\kk(\gl_{n|1})$ (resp. $\W^\kk(\sll_{n|1})$) the corresponding $\W$-superalgebra.

Let $\mathcal{A}_{\psi}$ denote the $bc$-system vertex superalgebra generated by odd fields $\psi, \psi^*$ satisfying the $\lambda$-brackets
\begin{align*}
\lm{\psi}{\psi^*}=1,\quad \lm{\psi}{\psi}=\lm{\psi^*}{\psi^*}=0.
\end{align*}
and $\pi_\h^{k+\dC}$ the Heisenberg vertex algebra associated with the Cartan subalgebra $\h$. By definition, it is generated by the fields $u_1,\cdots,u_{n+1}$ which correspond to $e_{1,1},\cdots, e_{n+1,n+1}$ and satisfy the $\lambda$-brackets
$$\lm{u_i}{u_j}=(k+\dC)\kk_V(u_i,u_j)\lambda.$$
For $\lambda \in \h^*$, let $\pi^{k+\dC}_{\h,\lambda}$ denote the Fock module over $\pi^{k+\dC}_{\h}$ of highest weight $\lambda$. 
For later convenience, we denote a non-zero highest weight vector by $\hwt{\frac{1}{k+\dC}\lambda}$ and thus it satisfies 
$$\lm{u_i}{\hwt{\frac{1}{k+\dC}\lambda}}=\lambda(u_i)\hwt{\frac{1}{k+\dC}\lambda}.$$
Let us introduce the following screening operators 
\begin{align}
    S_i:=\int Y(P_i \hwt{-\frac{1}{k+\dC}\alpha_i},z)\dz \colon \mathcal{A}_{\psi}\otimes \pi^{k+\dC}_{\h} \rightarrow \mathcal{A}_{\psi}\otimes \pi^{k+\dC}_{\h,-\alpha_i}
\end{align}

ref_dict.THM: FF center for gln1 vis pD op:
\begin{theorem}\label{THM: FF center for gln1 vis pD op}
The center $\cent(V^{\kk_c}(\gl_{n|1}))$ is isomorphic to the subalgebra in $\pi^0_\h$
strongly generated by the coefficients $W_p$ $(p\geq1)$ of the the pseudo-differential operator $\mathcal{L}$:
\begin{align}\label{eq: pD op}
\mathcal{L}=(\partial- u_1)\cdots (\partial- u_n) (\partial+u_{n+1})^{-1} 
 =\partial^{n-1}+ \sum_{p=1}^\infty W_p \partial^{n-1-p}.
\end{align}
\end{theorem}

ref_dict.them: Detecting the FF center:
\begin{theorem}\label{them: Detecting the FF center}\hspace{0mm}\\
\textup{(1)} The homomorphism $\iota$ is an isomorphism
\begin{align*}
\iota\colon \cent(V^{\kk_c}(\gl_{n|1}))\xrightarrow{\simeq} \cent(\W^{\kk_c}(\gl_{n|1})).
\end{align*}
\textup{(2)} There is an isomorphism of differential algebras 
\begin{align*}
 \gr\cent(V^{\kk_c}(\gl_{n|1}))\simeq \Lambda^{n|1}_{\aff}.
\end{align*}
\end{theorem}

ref_dict.cor: characters as plane partition count:
\begin{corollary}\label{cor: characters as plane partition counting} For all $n\geq 1$, 
    \begin{align*}
        \ch[\cent(V^{\kk_c}(\gl_{n|1}))](q)=\sum_{\begin{subarray}c \lambda \in \mathrm{PP}\\ (2,n+1)\notin \lambda \end{subarray}} q^{|\lambda|}.
    \end{align*}
\end{corollary}

ref_dict.thm: character formula of the center:
\begin{theorem}\label{thm: character formula of the center}
For all $n\geq1$, the following formula holds:
\begin{align*}
    \ch[\cent(V^{\kk_c}(\gl_{n|1}))](q)=\frac{\sum_{m=0}^\infty (-1)^mq^{\frac{1}{2}m(m+1)}(q^{m+1};q)_{n-1}}{(q;q)_\infty^2(q,\cdots,q^{n-1};q)_\infty}.
\end{align*}
\end{theorem}

ref_dict.prop: coset for Wsalg:
\begin{theorem}\label{prop: coset for Wsalg}
For $k\neq-\dC+1$, the elements $W_p$ $(p \geq 1)$ lie in the coset $C^\kk(\gl_{n|1})$. Moreover, they strongly generate $C^\kk(\gl_{n|1})$ for generic $\kk$.
\end{theorem}

