theorem.content:
\label{thm:main}
	Let $ F$ be a finite extension of $\QQ_p$, let $\chi\in\Irr(\mathcal G)$, and let $\eta\mid\res^\G_H\chi$ be an irreducible constituent. Then for the $\chi$-component in the Wedderburn decomposition \eqref{eq:QFG-Wedderburn},
	\begin{theoremlist}
		\item the size of the matrix ring is $n_{F,\chi} = n_\eta v_{F,\chi}$, \label{item:main-n}
		\item the Schur index of $D_{F,\chi}$ is $s_{F,\chi} = s_\eta (F(\eta):F_\chi)$, \label{item:main-s}
		\item the skew field is isomorphic to the total ring of quotients of a skew power series ring: $D_{F,\chi} \simeq \Quot\left(\OO_{D_\eta}[[X; \tau_F, \tau_F-\id]]\right)$. \label{item:main-D}
	\end{theoremlist}

ref_dict.item:main-D:
\begin{theoremlist}
		\item the size of the matrix ring is $\nFchi = n_\eta \vf$, \label{item:main-n}
		\item the Schur index of $\DFchi$ is $\sFchi = s_\eta (F(\eta):F_\chi)$, \label{item:main-s}
		\item the skew field is isomorphic to the total ring of quotients of a skew power series ring: $\DFchi \simeq \Quot\left(\OO_{D_\eta}[[X; \tauf, \tauf-\id]]\right)$. \label{item:main-D}
	\end{theoremlist}

ref_dict.cor:max-orders:
\begin{corollary} \label{cor:max-orders}
Every maximal $\Lambda^{\OO_F}(\Gamma_0)$-order in $\Q^F(\G)$ is isomorphic to one of the form
\[\bigoplus_{\chi\in\Irr(\G)/\sim_{ F}} u_\chi M_{\nFchi} \left( \OO_{D_\eta}[[X; \tauf, \tauf-\id]] \right) u_\chi^{-1} ,\]
where $u_\chi\in \GL_{\nFchi}\left(\Quot\left(\OO_{D_\eta}[[X; \tauf, \tauf-\id]]\right)\right)$.
\end{corollary}

