theorem.content:
[see Propositions~\ref{prop:irredtriv} and \ref{prop:sgnirred}]\label{thmintroA}
    The representation $\pi_{\varepsilon,s}$ is reducible if and only if
    \begin{itemize}
        \item $\varepsilon=0$ and $s\in\mathbb{Z}\cup(2+\frac{2}{3}\ZZ_{\geq0})\cup(1-\frac{2}{3}\ZZ_{\geq0})$, or
        \item $\varepsilon=1$ and $s\in\mathbb{Z}\cup(\frac{7}{3}+\frac{2}{3}\ZZ_{\geq0})\cup(\frac{2}{3}-\frac{2}{3}\ZZ_{\geq0})$.
    \end{itemize}

ref_dict.thm:ClosedFormulasIntertwinerEigenvalues:
\begin{theorem}\label{thm:ClosedFormulasIntertwinerEigenvalues}
	The eigenvalues $\mu_k(n,m,s)$ of $A_{n,m}(s)$ are given in terms of the eigenvalues on multiplicity-one $K$-types as follows, where $m,r\in\ZZ_{\geq0}$:
    \begin{enumerate}
        \item The eigenvalues of $A_{3m+2r,m}(s)$ are given by
        \begin{align*}
            \mu_{2j}(3m+2r,m,s) &=
            \frac{(\frac{r+3\tilde{s}+2j-3}{2})_{2j}(\frac{r+\tilde{s}}{2}+j)_j(\frac{r-\tilde{s}}{2}+j+1)_{j}(r+\tilde{s}+4j)_{m-2j}}{(\frac{r+3s+2j-3}{2})_{2j}(\frac{r+s}{2}+j)_j(\frac{r-s}{2}+j+1)_{j}(r+s+4j)_{m-2j}}A_{2(r+2j),0}(s),\\
            \mu_{2j+1}(3m+2r,m,s) &=
            \frac{(\frac{r+3\tilde{s}+2j-2}{2})_{2j+1}(\frac{r+\tilde{s}+1}{2}+j)_{j}(\frac{r-\tilde{s}+3}{2}+j)_{j}(r+\tilde{s}+4j+1)_{m-2j-1}}{(\frac{r+3s+2j-2}{2})_{2j+1}(\frac{r+s+1}{2}+j)_{j}(\frac{r-s+3}{2}+j)_{j}(r+s+4j+1)_{m-2j-1}}A_{2(r+2j+1),0}(s).
	   \end{align*}
       \item The eigenvalues of $A_{3m,m+2r}(s)$ are given by
       \begin{align*}
           \mu_{2j}(3m,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j-1}{2})_{2j}(\frac{r+\tilde{s}}{2}+j)_j(\frac{r-\tilde{s}}{2}+j+1)_j(r+\tilde{s}+4j)_{m-2j}}{(\frac{s-r-2j-1}{2})_{2j}(\frac{r+s}{2}+j)_j(\frac{r-s}{2}+j+1)_j(r+s+4j)_{m-2j}} A_{0,2(r+2j)}(s),\\
           \mu_{2j+1}(3m,m+2r,s) &= \frac{(\frac{\tilde{s}-2j-r-2}{2})_{2j+1}(\frac{r+\tilde{s}+1}{2}+j)_j(\frac{r-\tilde{s}+3}{2}+j)_j(r+\tilde{s}+4j+1)_{m-2j-1}}{(\frac{s-2j-r-2}{2})_{2j+1}(\frac{r+s+1}{2}+j)_j(\frac{r-s+3}{2}+j)_j(r+s+4j+1)_{m-2j-1}} A_{0,2(r+2j+1)}(s).
       \end{align*}
       \item The eigenvalues of $A_{3m+2,m+2r}(s)$ are given by
       \begin{align*}
           \mu_{2j}(3m+2,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j}{2})_{2j}(\frac{r+\tilde{s}+1}{2}+j)_j(\frac{r-\tilde{s}+3}{2}+j)_j(r+\tilde{s}+4j+1)_{m-2j}}{(\frac{s-r-2j}{2})_{2j}(\frac{r+s+1}{2}+j)_j(\frac{r-s+3}{2}+j)_j(r+s+4j+1)_{m-2j}}A_{2,2(r+2j)}(s),\\
           \mu_{2j+1}(3m+2,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j-1}{2})_{2j+1}(\frac{r+\tilde{s}}{2}+j+1)_j(\frac{r-\tilde{s}}{2}+j+2)_j(r+\tilde{s}+4j+2)_{m-2j-1}}{(\frac{s-r-2j-1}{2})_{2j+1}(\frac{r+s}{2}+j+1)_j(\frac{r-s}{2}+j+2)_j(r+s+4j+2)_{m-2j-1}}A_{2,2(r+2j+1)}(s).
       \end{align*}
       \item The eigenvalues of $A_{3m+4,m+2r}(s)$ are given by
       \begin{align*}
           \mu_{2j}(3m+4,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j+1}{2})_{2j}(\frac{r+\tilde{s}}{2}+j+1)_j(\frac{r-\tilde{s}}{2}+j+2)_j(r+\tilde{s}+4j+2)_{m-2j}}{(\frac{s-r-2j+1}{2})_{2j}(\frac{r+s}{2}+j+1)_j(\frac{r-s}{2}+j+2)_j(r+s+4j+2)_{m-2j}}A_{4,2(r+2j)}(s),\\
           \mu_{2j+1}(3m+4,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j}{2})_{2j+1}(\frac{r+\tilde{s}+2j+3}{2})_j(\frac{r-\tilde{s}+2j+5}{2})_j(r+\tilde{s}+4j+3)_{m-2j-1}}{(\frac{s-r-2j}{2})_{2j+1}(\frac{r+s+2j+3}{2})_j(\frac{r-s+2j+5}{2})_j(r+s+4j+3)_{m-2j-1}}A_{4,2(r+2j+1)}(s).
       \end{align*}
    \end{enumerate}
\end{theorem}

ref_dict.thm:LDS:
\begin{theorem}\label{thm:LDS}
The kernel 
$\ker(A(1,2))$
is
isomorphic to the limit of discrete series $\pi_4^{\textup{GW}}$.
\end{theorem}

ref_dict.prop:irredtriv:
\begin{proposition}
\label{prop:irredtriv}
The representation $\pi_{0,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(2+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

ref_dict.thmintroC:
\begin{thmalph}[see Propositions~\ref{prop:ladderker} and \ref{prop:doubleladderker}]\label{thmintroC}
    \begin{itemize}
        \item The ladder representation $\pi_{\mathrm{min}}$ of $G$ is the kernel of the intertwining operator $A(1,s)$ at $s=\frac{2}{3}$.
        \item The double ladder representation $\pi_{\mathrm{small}}$ of $G$ is the kernel of the intertwining operator $A(0,s)$ at $s=\frac{1}{3}$.
    \end{itemize}
\end{thmalph}

ref_dict.prop:doubleladderker:
\begin{proposition}
\label{prop:doubleladderker}
The kernel of the intertwining operator $(s-\frac{1}{3})A(0,s):I(0,s)\to I(0,\tilde{s})$ at $s = \frac{1}{3}$ is the double ladder representation of $G$. It is also the image of the intertwiner $A(0,\tilde{s}):I(0,\tilde{s})\to I(0,s)$. Moreover, this subrepresentation has $K$-types $\sigma(3m,m)$ and $\sigma(3m+4,m)$ ($m\in\ZZ_{\geq0}$) with corresponding embedding vectors $v_{3m,m}(s,0)$ and $v_{3m+4,m}(s,0)$.
\end{proposition}

ref_dict.thm:QDS:
\begin{theorem}\label{thm:QDS}
Let $k\geq6$ be even and let $s=\frac{k}{2}$, $\varepsilon\equiv\frac{k}{2}+1\pmod2$. Then the second level $I(\varepsilon,s)_2$ of the Jantzen filtration of $I(\varepsilon,s)$ is isomorphic to the quaternionic discrete series representation $\pi_k^{\textup{GW}}$.
\end{theorem}

ref_dict.prop:sgnirred:
\begin{proposition}
\label{prop:sgnirred}
The representation $\pi_{1,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(\frac{7}{3}+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

ref_dict.thmintroD:
\begin{thmalph}[see Theorems~\ref{thm:LDS} and \ref{thm:QDS}]\label{thmintroD}
    \begin{itemize}
        \item The limit of discrete series $\pi_4^{\textup{GW}}$ is isomorphic to the kernel of the intertwining operator $A(\varepsilon,s)$ for $s=2$, $\varepsilon\equiv1\pmod2$.
        \item The quaternionic discrete series representation $\pi^{\textup{GW}}_k$ ($k\geq6$ even) is isomorphic to the subrepresentation of $\pi_{\varepsilon,s}$ for $s=\frac{k}{2}$, $\varepsilon\equiv\frac{k}{2}+1\pmod2$, consisting of those vectors on which the intertwining operator $A(\varepsilon,s')$ vanishes of order two at $s'=s$.
    \end{itemize}
\end{thmalph}

