In the \subsection*{Method of proof} the authors explain that the restriction of the degenerate principal series $\pi_{\varepsilon,s}$ to $K$ "is not multiplicity-free", so studying the underlying $(\mathfrak{g}_\mathbb{C},K)$-module is difficult because transitions between $K$-types are given by "a linear map between the multiplicity spaces." Building on Kable, \emph{The degenerate principal series representations of $\mathrm{Sp}(2n,\mathbb{R})$} (2012), they "determine these maps explicitly":

\begin{proposition}
\label{Mmatrix}
	We have
    $$(\RC_{l}\boxtimes \RC_{l'})R_s^{\pm}(n,m)\zeta^{n,m}_{a}=M^{\pm}_{l,l'}\zeta^{n+3-2l,m+1-2l'}_{a\pm 1}, \qquad (0\le l\le 3, 0\le l'\le 1), $$
	where the matrices $M^\pm=(M^\pm_{l,l'})_{0\leq l\leq 3,0\leq l'\leq1}$ 
    are given by
	$$M^+:=\left(
	\begin{array}{cc}
		\frac{1}{2} (2s -2 a+m+n) & \frac{(a-m) (2s - 2 a - m-2 + n)}{4 m} \\
		\frac{(3 a-n) (6s - 6a -6 + 3 m + n)}{12 n} & \frac{(a-m) (3 a-n) (6 s - 6 a - 12 +n-3 m)}{24 m n} \\
		\frac{(3 a-n) (n - 3a - 2) (6 a- 6 s - 3 m+n+8)}{24 (n-1) n} & \frac{(a-m) (n - 3 a) (n - 3 a-2) (6s - 6 a - 14 - 3 m - n)}{48 m (n-1) n} \\
		\frac{(n - 3a) (n - 3 a - 2) (n - 3 a - 4) (2 a - 2s -m+n+2)}{16 (n-2) (n-1) n} & \frac{(a-m) (3 a-n) (n - 3 a - 2) (n - 3 a - 4) (2s - 2 a - 4 - m - n)}{32 m (n-2) (n-1) n} \\
	\end{array}
	\right)
    $$
    and
    $$M^-:=	\left( \begin{array}{cc}
		- \frac{1}{2} (2s + 2 a+m+n) & \frac{(-a-m) (2s + 2 a - m-2 + n)}{4 m} \\
		\frac{(- 3 a-n) (6s + 6a -6 + 3 m + n)}{12 n} & \frac{(a+m) (-3 a-n) (6 s + 6 a - 12 +n-3 m)}{24 m n} \\
		\frac{(3 a+n) (n + 3a - 2) (-6 a- 6 s - 3 m+n+8)}{24 (n-1) n} & \frac{(-a-m) (n + 3 a) (n + 3 a-2) (6s + 6 a - 14 - 3 m - n)}{48 m (n-1) n} \\
		\frac{(n + 3a) (n + 3 a - 2) (n + 3 a - 4) (- 2 a - 2s -m+n+2)}{16 (n-2) (n-1) n} & \frac{(a+m) (- 3 a-n) (n + 3 a - 2) (n + 3 a - 4) (2s + 2 a - 4 - m - n)}{32 m (n-2) (n-1) n} \\
	\end{array}
	\right).$$
\end{proposition}

and "identify a convenient basis of every multiplicity space" adapted to these transitions (next they prove this).

With respect to this basis, "the action of the Knapp--Stein intertwining operators on each $K$-isotypic component is upper triangular" and they "determine the corresponding eigenvalues". First, on the multiplicity-one $K$-types they obtain:

\begin{corollary}\label{cor:ClosedFormulasIntertwinerMultOneKtypes}
For $r\in\ZZ_{\geq0}$ and $s\in\CC$, $\tilde{s}=3-s$:
\begin{align*}
    A_{4r,0} &= \frac{(\frac{\tilde{s}}{2})_r(\frac{3\tilde{s}-3}{2})_r}{(\frac{s}{2})_r(\frac{3s-3}{2})_r} A_{0,0}, & A_{4r+2,0}  &= \frac{(\frac{\tilde{s}+1}{2})_r(\frac{3\tilde{s}-2}{2})_r}{(\frac{s+1}{2})_r(\frac{3s-2}{2})_r} A_{2,0},\\
    A_{0,4r} &= \frac{(\frac{\tilde{s}}{2})_r^2(\frac{3\tilde{s}-1}{6})_{r}(\frac{3\tilde{s}+1}{6})_{r}}{(\frac{s}{2})_r^2(\frac{3s-1}{6})_{r}(\frac{3s+1}{6})_{r}} A_{0,0}, &  A_{0,4r+2} &= \frac{(\frac{\tilde{s}+1}{2})_r(\frac{\tilde{s}-1}{2})_{r+1}(\frac{3\tilde{s}+2}{6})_{r}(\frac{3\tilde{s}-2}{6})_{r+1}}{   (\frac{s+1}{2})_r(\frac{s-1}{2})_{r+1}(\frac{3s+2}{6})_{r}(\frac{3s-2}{6})_{r+1}  } A_{2,0},\\
	A_{2,4r+2} &= \frac{(\frac{\tilde{s}}{2})_{r+1}(\frac{\tilde{s}}{2})_r(\frac{3\tilde{s}+1}{6})_r(\frac{3\tilde{s}-1}{6})_{r+1}}{(\frac{s}{2})_{r+1}(\frac{s}{2})_r(\frac{3s+1}{6})_r(\frac{3s-1}{6})_{r+1}} A_{0,0}, & A_{2,4r} &= \frac{(\frac{\tilde{s}+1}{2})_{r}(\frac{\tilde{s}-1}{2})_r(\frac{3\tilde{s}+2}{6})_r(\frac{3\tilde{s}-2}{6})_{r}}{(\frac{s+1}{2})_{r}(\frac{s-1}{2})_r(\frac{3s+2}{6})_r(\frac{3s-2}{6})_{r}} A_{2,0},\\
    A_{4,4r} &= \frac{(\frac{\tilde{s}}{2})_{r-1}(\frac{\tilde{s}}{2})_{r+1}(\frac{3\tilde{s}-1}{6})_r(\frac{3\tilde{s}+1}{6})_r}{(\frac{s}{2})_{r-1}(\frac{s}{2})_{r+1}(\frac{3s-1}{6})_r(\frac{3s+1}{6})_r}A_{0,0}, & A_{4,4r+2} &= \frac{(\frac{\tilde{s}+1}{2})_{r+1}(\frac{\tilde{s}-1}{2})_{r}(\frac{3\tilde{s}+2}{6})_{r}(\frac{3\tilde{s}-2}{6})_{r+1}}{(\frac{s+1}{2})_{r+1}(\frac{s-1}{2})_{r}(\frac{3s+2}{6})_{r}(\frac{3s-2}{6})_{r+1}} A_{2,0}.
\end{align*}
\end{corollary}

More generally, they determine eigenvalues on all $K$-types as follows.

\begin{theorem}\label{thm:ClosedFormulasIntertwinerEigenvalues}
	The eigenvalues $\mu_k(n,m,s)$ of $A_{n,m}(s)$ are given in terms of the eigenvalues on multiplicity-one $K$-types as follows, where $m,r\in\ZZ_{\geq0}$:
    \begin{enumerate}
        \item The eigenvalues of $A_{3m+2r,m}(s)$ are given by
        \begin{align*}
            \mu_{2j}(3m+2r,m,s) &=
            \frac{(\frac{r+3\tilde{s}+2j-3}{2})_{2j}(\frac{r+\tilde{s}}{2}+j)_j(\frac{r-\tilde{s}}{2}+j+1)_{j}(r+\tilde{s}+4j)_{m-2j}}{(\frac{r+3s+2j-3}{2})_{2j}(\frac{r+s}{2}+j)_j(\frac{r-s}{2}+j+1)_{j}(r+s+4j)_{m-2j}}A_{2(r+2j),0}(s),\\
            \mu_{2j+1}(3m+2r,m,s) &=
            \frac{(\frac{r+3\tilde{s}+2j-2}{2})_{2j+1}(\frac{r+\tilde{s}+1}{2}+j)_{j}(\frac{r-\tilde{s}+3}{2}+j)_{j}(r+\tilde{s}+4j+1)_{m-2j-1}}{(\frac{r+3s+2j-2}{2})_{2j+1}(\frac{r+s+1}{2}+j)_{j}(\frac{r-s+3}{2}+j)_{j}(r+s+4j+1)_{m-2j-1}}A_{2(r+2j+1),0}(s).
	   \end{align*}
       \item The eigenvalues of $A_{3m,m+2r}(s)$ are given by
       \begin{align*}
           \mu_{2j}(3m,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j-1}{2})_{2j}(\frac{r+\tilde{s}}{2}+j)_j(\frac{r-\tilde{s}}{2}+j+1)_j(r+\tilde{s}+4j)_{m-2j}}{(\frac{s-r-2j-1}{2})_{2j}(\frac{r+s}{2}+j)_j(\frac{r-s}{2}+j+1)_j(r+s+4j)_{m-2j}} A_{0,2(r+2j)}(s),\\
           \mu_{2j+1}(3m,m+2r,s) &= \frac{(\frac{\tilde{s}-2j-r-2}{2})_{2j+1}(\frac{r+\tilde{s}+1}{2}+j)_j(\frac{r-\tilde{s}+3}{2}+j)_j(r+\tilde{s}+4j+1)_{m-2j-1}}{(\frac{s-2j-r-2}{2})_{2j+1}(\frac{r+s+1}{2}+j)_j(\frac{r-s+3}{2}+j)_j(r+s+4j+1)_{m-2j-1}} A_{0,2(r+2j+1)}(s).
       \end{align*}
       \item The eigenvalues of $A_{3m+2,m+2r}(s)$ are given by
       \begin{align*}
           \mu_{2j}(3m+2,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j}{2})_{2j}(\frac{r+\tilde{s}+1}{2}+j)_j(\frac{r-\tilde{s}+3}{2}+j)_j(r+\tilde{s}+4j+1)_{m-2j}}{(\frac{s-r-2j}{2})_{2j}(\frac{r+s+1}{2}+j)_j(\frac{r-s+3}{2}+j)_j(r+s+4j+1)_{m-2j}}A_{2,2(r+2j)}(s),\\
           \mu_{2j+1}(3m+2,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j-1}{2})_{2j+1}(\frac{r+\tilde{s}}{2}+j+1)_j(\frac{r-\tilde{s}}{2}+j+2)_j(r+\tilde{s}+4j+2)_{m-2j-1}}{(\frac{s-r-2j-1}{2})_{2j+1}(\frac{r+s}{2}+j+1)_j(\frac{r-s}{2}+j+2)_j(r+s+4j+2)_{m-2j-1}}A_{2,2(r+2j+1)}(s).
       \end{align*}
       \item The eigenvalues of $A_{3m+4,m+2r}(s)$ are given by
       \begin{align*}
           \mu_{2j}(3m+4,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j+1}{2})_{2j}(\frac{r+\tilde{s}}{2}+j+1)_j(\frac{r-\tilde{s}}{2}+j+2)_j(r+\tilde{s}+4j+2)_{m-2j}}{(\frac{s-r-2j+1}{2})_{2j}(\frac{r+s}{2}+j+1)_j(\frac{r-s}{2}+j+2)_j(r+s+4j+2)_{m-2j}}A_{4,2(r+2j)}(s),\\
           \mu_{2j+1}(3m+4,m+2r,s) &= \frac{(\frac{\tilde{s}-r-2j}{2})_{2j+1}(\frac{r+\tilde{s}+2j+3}{2})_j(\frac{r-\tilde{s}+2j+5}{2})_j(r+\tilde{s}+4j+3)_{m-2j-1}}{(\frac{s-r-2j}{2})_{2j+1}(\frac{r+s+2j+3}{2})_j(\frac{r-s+2j+5}{2})_j(r+s+4j+3)_{m-2j-1}}A_{4,2(r+2j+1)}(s).
       \end{align*}
    \end{enumerate}
\end{theorem}

This "allows" them, in establishing the main theorem, to deduce the complementary series criterion; namely,
\begin{coralph}[see Corollary~\ref{cor:ComplementarySeries}]\label{corintroB}
    For $\varepsilon\in\ZZ/2\ZZ$ and $s\in\RR$ the representation $\pi_{\varepsilon,s}$ is irreducible and unitarizable if and only if $s\in(1,2)$.
\end{coralph}

