\begin{proposition}
\label{prop:irredtriv}
The representation $\pi_{0,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(2+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

\begin{proposition}
\label{prop:sgnirred}
The representation $\pi_{1,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(\frac{7}{3}+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

\label{thmintroA}
    The representation $\pi_{\varepsilon,s}$ is reducible if and only if
    \begin{itemize}
        \item $\varepsilon=0$ and $s\in\mathbb{Z}\cup(2+\frac{2}{3}\ZZ_{\geq0})\cup(1-\frac{2}{3}\ZZ_{\geq0})$, or
        \item $\varepsilon=1$ and $s\in\mathbb{Z}\cup(\frac{7}{3}+\frac{2}{3}\ZZ_{\geq0})\cup(\frac{2}{3}-\frac{2}{3}\ZZ_{\geq0})$.
