ref_dict.thm : existence of morphisms eta:
\begin{thm} \label{thm : existence of morphisms eta}
    There exists a family of irreducible morphisms 
    $$\{\eta_i^{(X,h)}   \in \mathrm{Hom}_{\HQ^{(1)}} \left( (X,h) , \mu_i (X,h) \right) , \enspace \text{$(X,h)$ indecomposable in $\HQ^{(1)}$}, i \in \Sigma(X,h) \}$$ 
    satisfying the following properties:
     \begin{enumerate}
         \item For every $i \in \Sigma(X,h)$ and every $j \in I$ such that  $j \rightsquigarrow i$ in $Q$, we have that  
         $$j \in \Sigma( \mu_i(X,h)) \qquad \text{and} \qquad  \eta_j^{\mu_i(X,h)} \circ \eta_i^{(X,h)} = 0 . $$ 
         \item For any object $T$ in $\HQ^{(1)}$, and any morphism $f \in \mathrm{Hom}_{\HQ^{(1)}}(\mu_i(X,h), T)$, we have that 
         $$ f \circ \eta_i^{(X,h)} = 0 \quad \Rightarrow \quad \text{$f$ factors through $\bigoplus_{ \substack{j \rightsquigarrow i \\ j \in \Sigma(\mu_i(X,h))}} \eta_j^{\mu_i(X,h)}$.} $$
     \end{enumerate}
  \end{thm}

ref_dict.thm : thm1 intro:
\begin{thm} \label{thm : thm1 intro}
      For each positive (or negative simple) root $\beta$, there exists a unique (up to isomorphism) strongly $\HQ^{(1)}$-exact complex $C_{\bullet}[\beta]$ in $\KQ^{(1)}$ such that $C_n[\beta]=0$ if $n<0$ and $C_0[\beta]$ is indecomposable and isomorphic to $Y[\beta]$. 
  \end{thm}

ref_dict.def : Serre tiltings:
\begin{deftn} \label{def : Serre tiltings}
 Given any indecomposable object $(X,h)$ in $\tMQ$ and any \textit{finite} subset $Y = \{ y_1 , \ldots  , y_r\} \subseteq X$, we define the \textbf{Serre tilting} of $(X,h)$ at $Y$ as the object of $\tMQ$ given by  
 $$ \mu_Y(X,h) := \left(  (X \setminus Y) \sqcup SY \enspace , \enspace  h - \sum_{y \in Y} \delta_y \right) $$
 where $SY$ stands for $SY := \{S y_1, \ldots , S y_r\}$.  For simplicity we will write $\mu_y(X)$ for $\mu_{\{y \}}(X)$.
   \end{deftn}

