\begin{remark} \label{NonIsomGradedLimit}
    Since the frogetful functor in \Cref{PropertiesDgrZ}\Cref{ForgetfulFunctorDgrZ} preserves all colimits, it is exact and especially it preserves finite limits (\cite[Proposition 1.1.4.1]{lurie2017Higher}).
    However, this does not preserve (infinite) limits in general.
    For example, take \(G = \setZ_{\geq 0}\) and consider the diagram \(F \colon \setZ_{\geq 0} \to \mcalD_{\graded{G}}(\setZ)\) given by \(F(n) = \setZ[X]/(X^n)\) with \(\deg(X) = 1\) and the natural projection morphisms.
    Then, we can show that
    \begin{equation*}
        \grlim_{n \geq 0} \setZ[X]/(X^n) \cong \setZ[X] \quad \text{in } \mcalD_{\graded{G}}(\setZ)
    \end{equation*}
    but the usual limit \(\lim_{n \geq 0} \setZ[X]/(X^n)\) in \(\mcalD(\setZ)\) is isomorphic to the ring of formal power series \(\setZ[|X|]\).
\end{remark}

ref_dict.intro:
\begin{theoremA}[{\Cref{ComonadicityGradedModules}}]\label{intro}
    Let $\rho_R \colon R \to R[G]$ be the $\setZ[G]$-coaction induced by the $G$-grading on $R$ (see \Cref{def-coaction}).
    Then there exists an equivalence of \(\infty\)-categories
    \begin{align*}
        \mcalD_{\graded{G}}^{\comp{I}}(R) & \xrightarrow{\simeq} \coMod_{G}^{\comp{I}}(R); \\
        M & \mapsto (\dcomp{I}{M}, \rho \colon \dcomp{I}{M} \to \dcomp{I}{M[G]})
    \end{align*}
    where \(\dcomp{I}{-} \colon \mcalD(R) \to \mcalD^{\comp{I}}(R)\) is the derived \(I\)-completion functor, the derived \(R\)-module \(M[G]\) is defiend by \(\rho_{R, *}(M \otimes^L_R R[G])\), and $\coMod_{G}^{\comp{I}}(R)$ is the \(\infty\)-category of comodules over the comonad \(\mcalT^I \colon M \mapsto \dcomp{I}{M[G]}\) on \(\mcalD^{\comp{I}}(R)\).\footnote{As we will explain in \Cref{RemarkComoduleNotation}, the \(\infty\)-category \(\coMod_G^{\comp{I}}(R)\) is \emph{NOT} necessarily the \(\infty\)-category of comodules over the coalgebra \(\dcomp{I}{R[G]}\) in \(\mcalD^{\comp{I}}(R)\) unless the grading of \(R\) is trivial}
\end{theoremA}

ref_dict.LimitCommutative:
\begin{theorem} \label{LimitCommutative}
    Let $R$ be a $G$-graded ring and let $I$ be a finitely generated homogeneous ideal of \(R\).
    Take a diagram \(\{M_j\}_{j \in J} \colon J \to \mcalD_{\graded{G}}^{\comp{I}}(R)\) indexed by a (not necessarily small) simplicial set \(J\).
    Assume the existence of the limits of the diagrams
    \begin{align*}
        \{\mcalF^I(M_j)\}_{j \in J} = \{\dcomp{I}{M_j}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \quad \text{and} \\
        \{\mcalT^I(\mcalF^I(M_j))\} = \{\dcomp{I}{M_j}\abracket{G}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \abracket{G}.
    \end{align*}
    If the natural morphism
    \begin{equation} \label{AssumptionIsomMorphism}
        (\lim_{J} \dcomp{I}{M_j})\abracket{G} \to \lim_{J}(\dcomp{I}{M_j}\abracket{G})
    \end{equation}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), then the limit $\grlim_{J} M_j$ of $\{M_j\}_{j \in J}$ exists in $\mcalD_{\graded{G}}^{\comp{I}}(R)$, and the natural morphism
    \begin{equation*}
        \mcalF^I(\grlim_{J} M_j) = \dcomp{I}{\grlim_{J} M_j} \to \lim_{J} \dcomp{I}{M_j} = \lim_{J} \mcalF^I(M_j)
    \end{equation*}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), i.e., the limit is preserved by the functor \(\mcalF^I\).
\end{theorem}

ref_dict.RemarkComoduleNotation:
\begin{remark} \label{RemarkComoduleNotation}
    The notation \(\coMod_G^{\comp{I}}(R)\) does \emph{NOT} mean the \(\infty\)-category of comodules over the derived \(I\)-complete coalgebra \(R\abracket{G}\) in \(\mcalD^{\comp{I}}(R)\).
    Actually, the defining comonad \(\mcalT^I\) is just
    \begin{equation*}
        M \mapsto \dcomp{I}(\rho_{R, *}(M \otimes^L_R R\abracket{G}))
    \end{equation*}
    and not \(M \to M \widehat{\otimes}^L_R R\abracket{G}\).

    On the other hand, when \(R\) has the trivial \(G\)-grading, this notation \(\coMod_G^{\comp{I}}(R)\) coincides with the \(\infty\)-category \(\coMod_G^{\comp{I}}(R)\) of derived \(I\)-complete comodules over the coalgebra \(R\abracket{G}\) in \(\mcalD^{\comp{I}}(R)\) by \Cref{RemarkTrivialGradingComonad}.
\end{remark}

