One key ingredient in establishing the main theorem is verifying a sufficient condition ensuring that a diagram whose limit is preserved under the functor
\[
\mcalF^I \colon \mcalD_{\graded{G}}^{\comp{I}}(R) \xrightarrow{\mathrm{forget}} \mcalD(R) \xrightarrow{\dcomp{I}{-}} \mcalD^{\comp{I}}(R).
\]
We first prove the following theorem.

\begin{theorem} \label{LimitCommutative}
    Let $R$ be a $G$-graded ring and let $I$ be a finitely generated homogeneous ideal of \(R\).
    Take a diagram \(\{M_j\}_{j \in J} \colon J \to \mcalD_{\graded{G}}^{\comp{I}}(R)\) indexed by a (not necessarily small) simplicial set \(J\).
    Assume the existence of the limits of the diagrams
    \begin{align*}
        \{\mcalF^I(M_j)\}_{j \in J} = \{\dcomp{I}{M_j}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \quad \text{and} \\
        \{\mcalT^I(\mcalF^I(M_j))\} = \{\dcomp{I}{M_j}\abracket{G}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \abracket{G}.
    \end{align*}
    If the natural morphism
    \begin{equation} \label{AssumptionIsomMorphism}
        (\lim_{J} \dcomp{I}{M_j})\abracket{G} \to \lim_{J}(\dcomp{I}{M_j}\abracket{G})
    \end{equation}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), then the limit $\grlim_{J} M_j$ of $\{M_j\}_{j \in J}$ exists in $\mcalD_{\graded{G}}^{\comp{I}}(R)$, and the natural morphism
    \begin{equation*}
        \mcalF^I(\grlim_{J} M_j) = \dcomp{I}{\grlim_{J} M_j} \to \lim_{J} \dcomp{I}{M_j} = \lim_{J} \mcalF^I(M_j)
    \end{equation*}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), i.e., the limit is preserved by the functor \(\mcalF^I\).
\end{theorem}

Combining this criterion with the following Barr--Beck--Lurie theorem yields the main theorem.

\begin{theorem}[{cf. \cite[Proposition 4.7.3.3 and Theorem 4.7.3.5]{lurie2017Higher}\footnote{We will use its comodule version. See, for example, \cite[Proposition 2.2 and Theorem 2.3]{banerjee2017Galois}.}}] \label{BarrBeckLurie}
    Let \(\mcalF \colon \mcalC \to \mcalD\) be a functor of \(\infty\)-categories admitting a right adjoint \(\mcalG \colon \mcalD \to \mcalC\).
    Then the composition \(\mcalT \defeq \mcalF \circ \mcalG\) becomes an (endomorphism) comonad on \(\mcalD\) and the left coaction \(\mcalF \to \mcalT \circ \mcalF\) of \(\mcalT\) on \(\mcalF\) is just the unit \(\id_{\mcalC} \to \mcalG \circ \mcalF\) of the adjunction \((\mcalF, \mcalG)\) composed with \(\mcalF\).
    This gives rise to a comparison functor
    \begin{equation*}
        \mcalF' \colon \mcalC \to \coMod_{\mcalT}(\mcalD)
    \end{equation*}
    of \(\infty\)-categories whose composition with the forgetful functor \(\coMod_{\mcalT}(\mcalD) \to \mcalD\) is equivalent to \(\mcalF\), where \(\coMod_{\mcalT}(\mcalD)\) is the \(\infty\)-category of comodules over \(\mcalT\) in \(\mcalD\).
    If \(\mcalF'\) is an equivalence of \(\infty\)-categories, then we say that the functor \(\mcalF\) is \emph{comonadic}.

    On the comonadicity, Barr--Beck--Lurie theorem states that the following two conditions are equivalent:
    \begin{enumerate}
        \item The functor \(\mcalF\) is comonadic.
        \item The functor \(\mcalF\) is conservative and for any \(\mcalF\)-split\footnote{Here, an \(\mcalF\)-split cosimplicial object is a cosimplicial object \(X^{\bullet}\) on \(\mcalC\) such that whose composition \(\mcalF(X^{\bullet}) \colon \Delta \xrightarrow{X^{\bullet}} \mcalC \xrightarrow{\mcalF} \mcalD\) is a split cosimplicial object in \(\mcalD\).} cosimplicial object \(X^{\bullet} \colon \Delta \to \mcalC\), the limit \(\lim_{\Delta} X^{\bullet}\) exists in \(\mcalC\) and is preserved by \(\mcalF\).
    \end{enumerate}
\end{theorem}

