ref_dict.eg:one_2blowup:
\begin{example}\label{eg:one_2blowup}
    Let $\varphi_1:X_{n,1}\rightarrow\bP^1$ be the $2$-blowup with center $p_1$ on the Hirzebruch surface $\pi:\bF_n\ra\bP^1$. For $n\in\{0,1,2\}$, $X_{n,1}$ is weak del Pezzo if $p_1$ is not on any $(-2)$-curve. If $\cF_{n,1}$ is the foliation induced by $T_{\varphi_1}$, then $\mu(\cF_{n,1})=3=\mu(T_{X_{n,1}})$ and it destabilizes $T_{X_{n,1}}$. Note that $\cF_{n,1}\neq T_{\varphi_1}$ since the fiber $\varphi^{-1}(\varphi(p_1))$ is non-reduced. 
\end{example}

ref_dict.eg:three_2blowup:
\begin{example}\label{eg:three_2blowup}
For $n\in\{0,1,2\}$, let $\varphi_3:X_{n,3}\rightarrow\bP^1$ be the $2$-blowup with center $p_3\in X_{n,2}$, a surface from Example \ref{eg:two_2blowup}. If $p_3$ is neither on any $(-2)$-curve of $\bF_n$ nor the fiber containing $p_1$ or $p_2$, then $X_{n,3}$ is weak del Pezzo and the foliation $\cF_{n,3}$ induced by $T_{\varphi_3}$ destabilizes $T_{X_{n,3}}$ with $\mu(\cF_{n,3})=1=\mu(T_{X_{n,3}})$. 
See Figure~\ref{fig:eg1.6} for a visualization. 
\end{example}

ref_dict.thm:nonsingular-wdP:
\begin{theorem}\label{thm:nonsingular-wdP}
Let $X$ be a nonsingular weak del Pezzo surface. If the tangent bundle $T_X$ is $(-K_X)$-slope unstable, then $X$ is either the Hirzebruch surface $\bF_n$ with $n\in\{0,1,2\}$, or $X\cong X_{n,1}, X_{n,2},$ or $X_{n,3}$ as described in Examples~\ref{eg:one_2blowup}, \ref{eg:two_2blowup}, and \ref{eg:three_2blowup}. In either case, $\cF$ is induced by the canonical fibration $X\rightarrow\bP^1$. 
\end{theorem}

ref_dict.eg:two_2blowup:
\begin{example}\label{eg:two_2blowup}
For $n\in\{0,1,2\}$, let $\varphi_2:X_{n,2}\rightarrow\bP^1$ be the $2$-blowup with center $p_2\in X_{n,1}$, a surface from Example \ref{eg:one_2blowup}. If $p_2$ is neither on any $(-2)$-curve of $\bF_n$ nor the fiber containing $p_1$, then $X_{n,2}$ is weak del Pezzo and the foliation $\cF_{n,2}$ induced by $T_{\varphi_2}$ destabilizes $T_{X_{n,2}}$ with $\mu(\cF_{n,2})=2=\mu(T_{X_{n,2}})$. 
\end{example}

