\label{conj: GP in introduction}
The following statements hold:
\begin{enumerate}
    \item \textbf{Multiplicity-one:} For every tempered L-parameter $\phi$ of $\Sp(W)$ and every tempered L-parameter $\widetilde{\phi}$ of $\Mp(W)$, we have
    \[
        \sum_{\pi \in \Pi_{\phi}} \; \sum_{\widetilde{\pi} \in \Pi_{\widetilde{\phi}}} 
        m\!\left(\pi \boxtimes \widetilde{\pi} \right) = 1.
    \]
    \item \textbf{Epsilon-dichotomy:} The unique pair $(\pi,\widetilde{\pi}) \in \Pi_{\phi} \times \Pi_{\widetilde{\phi}}$ such that
    \[
        m\!\left(\pi \boxtimes \widetilde{\pi}\right) = 1
    \]
    corresponds to the distinguished characters of component groups
    \[
        \eta_{\pi} \times \eta_{\widetilde{\pi}} = \eta_{\widetilde\phi} \times \eta_{\phi},
    \]
    where $\eta_{\widetilde\phi} \times \eta_{\phi}$ is defined in terms of local root numbers as follows:
    \begin{equation}\label{distigulished character}
\begin{cases}
    \eta_{N_1}(a)= \epsilon\left(M^a\otimes N_1,\psi\right)\cdot \det\left(M^a\right)(-1)^{\frac{\dim N_1}{2}}\cdot \det\left(N_1\right)(-1)^{\frac{\dim M^a}{2}};\\[5pt]

    \eta_{M} (b) = \epsilon\left(M\otimes N_1^b,\psi\right)\cdot \det\left(M\right)(-1)^{\frac{\dim N_1^b}{2}}\cdot \det\left(N_1^b\right)(-1)^{\frac{\dim M}{2}},
