  \caption{The new hyperbolic obstruction set $H$ for $N_n$, $n=2$, from \Cref{thm:new-hyperbolas-frame-set-Bn}. The hyperbolic segments, defined by \eqref{eq:hyperbolic-obstruction-b-interval}, are colored by their $ab$ values.}
